using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem;using MultiFPS;using MultiFPS.Gameplay;using MultiFPS.UI;using ROM.Progression;
namespace ROM.UI.Gameplay {
public sealed class RiftTradeItemTooltip:MonoBehaviour,IPointerEnterHandler,IPointerExitHandler,ISelectHandler,IDeselectHandler {
 public RiftLootAxe Item;public string ItemName;
 void Show(){if(Item==null)return;RiftAbilityTooltip.ShowItemAtCursor(gameObject,Item.RarityLabel+" · "+ItemName,"Rareza: "+Item.RarityLabel+"\nDos manos\nRequiere nivel "+Item.Level+" para equipar\nPoder del objeto: ×"+Item.Multiplier.ToString("0.##")+"\n"+ROM.UI.Sprint01.RiftInventoryItems.WeaponDetails(Item)+"\nDurabilidad: "+Item.DurabilityNow+" / "+Item.DurabilityMax+"\nEscala por nivel: ×"+Item.LevelPower.ToString("0.##")+" · Rareza: ×"+Item.RarityMultiplier.ToString("0.##"),Item.DisplayColor);}
 public void OnPointerEnter(PointerEventData e){Show();}public void OnPointerExit(PointerEventData e){RiftAbilityTooltip.Hide(gameObject);}public void OnSelect(BaseEventData e){Show();}public void OnDeselect(BaseEventData e){RiftAbilityTooltip.Hide(gameObject);}void OnDisable(){RiftAbilityTooltip.Hide(gameObject);}
}
public sealed class RiftTradeFrameMenu:MonoBehaviour,IPointerClickHandler {
 public void OnPointerClick(PointerEventData data){if(data.button!=PointerEventData.InputButton.Right)return;var hud=GetComponentInParent<RiftGameplayHUD>();var other=hud&&hud.SelectedTarget?GameManager.Players.FirstOrDefault(p=>p&&p.MyCharacter&&p.MyCharacter.Health==hud.SelectedTarget):null;if(other&&other!=ClientFrontend.ClientPlayerInstance&&!other.BOT)hud.GetComponent<RiftTradeUI>().Context(other,data.position);}
}
public sealed class RiftTradeUI:MonoBehaviour {
 RiftGameplayHUD hud;RectTransform layer,panel,menu;RiftTradeSnapshot shown;Font font;
 void Awake(){hud=GetComponent<RiftGameplayHUD>();font=hud.Theme.BodyFont;layer=Rect(hud.Design,"Trade overlay",Vector2.zero,new Vector2(740,610));layer.anchorMin=layer.anchorMax=new Vector2(.5f,.5f);layer.pivot=new Vector2(.5f,.5f);var hit=Rect(hud.TargetPanel,"Trade target frame input",Vector2.zero,Vector2.zero);hit.anchorMin=Vector2.zero;hit.anchorMax=Vector2.one;hit.offsetMin=hit.offsetMax=Vector2.zero;var graphic=hit.gameObject.AddComponent<Image>();graphic.color=Color.clear;graphic.raycastTarget=true;hit.gameObject.AddComponent<Button>().targetGraphic=graphic;hit.gameObject.AddComponent<RiftTradeFrameMenu>();RiftTradeClient.Changed+=Render;}
 void OnDestroy(){RiftTradeClient.Changed-=Render;if(RiftTradeClient.Current!=null&&Local&&Mirror.NetworkClient.active)Local.CmdCancelTrade(RiftTradeClient.Current.Token);RiftTradeClient.Receive("");}
 RiftJournalPlayer Local=>ClientFrontend.ClientPlayerInstance?ClientFrontend.ClientPlayerInstance.GetComponent<RiftJournalPlayer>():null;
 public void Context(PlayerInstance other,Vector2 screen){if(menu)Destroy(menu.gameObject);var design=(RectTransform)hud.Design;RectTransformUtility.ScreenPointToLocalPointInRectangle(design,screen,null,out var point);var pos=new Vector2(Mathf.Clamp(point.x-design.rect.xMin,4,Mathf.Max(4,design.rect.width-254)),Mathf.Clamp(point.y-design.rect.yMax,-design.rect.height+114,-4));menu=Rect(design,"Player context menu",pos,new Vector2(250,110));Button(menu,"Comerciar",0,0,250,50,()=>{if(Local&&other)Local.CmdRequestTrade(other.netId);Destroy(menu.gameObject);});Button(menu,"Invitar al grupo",0,55,250,50,()=>{if(ChatBehaviour._instance&&other)ChatBehaviour._instance.CmdInviteParty(other.netId);Destroy(menu.gameObject);});}
 void Update(){if(layer)layer.SetAsLastSibling();if(Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame){if(menu)Destroy(menu.gameObject);if(RiftTradeClient.Current!=null&&Local)Local.CmdCancelTrade(RiftTradeClient.Current.Token);}if(shown!=RiftTradeClient.Current)Render();}
 void Render(){shown=RiftTradeClient.Current;if(panel)Destroy(panel.gameObject);if(menu)Destroy(menu.gameObject);if(shown==null)return;panel=Rect(layer,"Trade dialog",Vector2.zero,new Vector2(740,590));var bg=panel.gameObject.AddComponent<Image>();bg.color=new Color(.035f,.028f,.055f,.98f);panel.gameObject.AddComponent<Button>().targetGraphic=bg;Label(panel,"COMERCIAR · "+shown.Other,24,18,690,34,23);Label(panel,shown.Notice,24,58,690,48,14);string token=shown.Token;int revision=shown.Revision;
 if(!shown.Accepted){Label(panel,shown.Incoming?"Te invita a intercambiar objetos.":"Esperando que acepte la solicitud…",24,130,690,60,20);if(shown.Incoming)Button(panel,"Aceptar solicitud",24,220,330,45,()=>Local.CmdAcceptTrade(token));Button(panel,shown.Incoming?"Rechazar":"Cancelar",385,220,330,45,()=>Local.CmdCancelTrade(token));return;}

 Label(panel,"TU OFERTA",24,118,320,30,17);Label(panel,"RECIBIRÁS",395,118,320,30,17);
 for(int i=0;i<RiftJournalPlayer.MaximumLootAxes;i++){var own=i<shown.Own.Count?shown.Own[i]:null;var incoming=i<shown.OtherItems.Count?shown.OtherItems[i]:null;var captured=own;Slot("Own offer "+i,own,24+(i%4)*80,156+(i/4)*80,64,own!=null?(UnityEngine.Events.UnityAction)(()=>Local.CmdTradeOffer(token,revision,captured.Id,false)):null,false);Slot("Other offer "+i,incoming,395+(i%4)*80,156+(i/4)*80,64,null,false);}
 Label(panel,"TU BOLSA · clic para ofrecer o retirar",24,325,690,30,15);int index=0;foreach(var item in shown.Available.Take(RiftJournalPlayer.MaximumLootAxes)){var id=item.Id;bool offered=shown.Own.Any(x=>x.Id==id);Slot("Bag item "+index,item,24+index*66,365,56,()=>Local.CmdTradeOffer(token,revision,id,!offered),offered);index++;}if(index==0)Label(panel,"No hay objetos transferibles sin equipar.",24,365,690,45,16);
 Label(panel,(shown.OwnConfirmed?"Confirmaste. ":"Revisá los objetos antes de confirmar. ")+(shown.OtherConfirmed?"El otro jugador confirmó.":""),24,485,690,35,15);var confirm=Button(panel,"Confirmar intercambio",24,533,330,42,()=>Local.CmdConfirmTrade(token,revision));confirm.interactable=!shown.OwnConfirmed&&(shown.Own.Count+shown.OtherItems.Count>0);Button(panel,"Cancelar",385,533,330,42,()=>Local.CmdCancelTrade(token));}

 void Slot(string name,RiftLootAxe item,float x,float y,float size,UnityEngine.Events.UnityAction action,bool offered){var root=Rect(panel,name,new Vector2(x,-y),new Vector2(size,size));var bg=root.gameObject.AddComponent<RiftHUDChrome>();bg.Cut=5;bg.Accents=false;bg.color=new Color(.035f,.027f,.05f,.98f);bg.Border=item!=null?item.DisplayColor:new Color(.28f,.24f,.34f,.8f);bg.raycastTarget=item!=null;
  if(item==null){var empty=Label(root,"—",0,0,size,size,22);empty.alignment=TextAnchor.MiddleCenter;empty.color=new Color(.3f,.27f,.36f);return;}
  var definition=RiftLootTuning.Load.Item(item.DefinitionId);var model=definition&&definition.Weapon?definition.Weapon.Model:null;if(model)ROM.UI.Sprint01.RiftItemArt.Place(root,model,4,4,size-8);else{var fallback=Label(root,"?",0,0,size,size,24);fallback.alignment=TextAnchor.MiddleCenter;}
  var level=Label(root,"Nv. "+item.Level,0,size-18,size,18,11);level.alignment=TextAnchor.MiddleCenter;level.color=item.DisplayColor;
  if(offered){var check=Label(root,"✓",size-18,0,18,18,16);check.color=new Color(.35f,1,.6f);}
  // Selectable blocks world steering over either side; received slots are read-only.
  var button=root.gameObject.AddComponent<Button>();button.targetGraphic=bg;if(action!=null)button.onClick.AddListener(action);
  var tip=root.gameObject.AddComponent<RiftTradeItemTooltip>();tip.Item=item;tip.ItemName=definition?definition.DisplayName:"Hacha";
 }
 static RectTransform Rect(Transform parent,string name,Vector2 pos,Vector2 size){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=size;return r;}
 Text Label(Transform p,string text,float x,float y,float w,float h,int size){var t=Rect(p,text,new Vector2(x,-y),new Vector2(w,h)).gameObject.AddComponent<Text>();t.font=font;t.text=text;t.fontSize=size;t.color=new Color(.93f,.9f,.98f);t.raycastTarget=false;return t;}
 Button Button(Transform p,string text,float x,float y,float w,float h,UnityEngine.Events.UnityAction action){var r=Rect(p,text,new Vector2(x,-y),new Vector2(w,h));var image=r.gameObject.AddComponent<Image>();image.color=new Color(.15f,.085f,.23f,.98f);var b=r.gameObject.AddComponent<Button>();b.targetGraphic=image;b.onClick.AddListener(action);var label=Label(r,text,8,4,w-16,h-8,16);label.alignment=TextAnchor.MiddleCenter;return b;}
}
}
